import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as s from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void; let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = s.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });
const all = ["issue", "comment", "project"] as const;

it("scenarios", async () => {
  const ent = await createTenant("vent", "enterprise");
  const st = await createTenant("vst", "starter");
  const q = (t: typeof ent, q: string, extra: object = {}) =>
    s.search(t.actors.member, { orgId: t.org.id, q, kinds: [...all], limit: 25, cursor: null, ...extra });

  await issueService.createIssue(st.actors.member, issueInput(st.org.id, st.project.id, { title: "Release 2: hotfix" }));
  const c0 = await issueService.createIssue(st.actors.member, issueInput(st.org.id, st.project.id, { title: "other" }));
  await commentService.createComment(st.actors.member, { orgId: st.org.id, issueId: c0.id, body: "hotfix comment", parentId: null, mentionedUserIds: [] });
  expect((await q(st, "Release 2: hotfix")).total).toBe(1);
  expect((await q(st, "hotfix")).items.map((h) => h.kind)).toEqual(["issue"]);

  const i1 = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "snake case 100 percent" }));
  const i2 = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "snake_case 100% deploy" }));
  const c = await commentService.createComment(ent.actors.member, { orgId: ent.org.id, issueId: i1.id, body: "flaky deploy", parentId: null, mentionedUserIds: [] });
  expect((await q(ent, "100%")).items.map((h) => h.id)).toEqual([i2.id]);
  expect((await q(ent, "snake_case")).items.map((h) => h.id)).toEqual([i2.id]);
  expect((await q(ent, "SNAKE_CASE")).total).toBe(1);
  expect((await q(ent, "kind:comment flaky", { kinds: ["issue"] })).items.map((h) => h.id)).toEqual([c.id]);
  expect((await q(ent, "in:comments flaky", { kinds: ["issue"] })).total).toBe(1);
  expect((await q(ent, `project:${ent.project.id} deploy`)).total).toBe(2);
  expect((await q(ent, "project:nope deploy")).total).toBe(0);
  expect((await q(ent, "flaky", { projectId: ent.project.id })).total).toBe(1);

  await searchRepo.deleteSearchDocument(ent.org.id, "comment", c.id);
  await searchRepo.deleteSearchDocument(ent.org.id, "project", ent.project.id);
  const env = { orgId: ent.org.id, actorId: null, occurredAt: new Date().toISOString() as never };
  await emit("search.reindex_requested", { ...env, subjectKind: "comment", subjectId: c.id });
  await emit("search.reindex_requested", { ...env, subjectKind: "project", subjectId: ent.project.id });
  expect((await q(ent, "flaky", { projectId: ent.project.id })).total).toBe(1);
  expect((await q(ent, "kind:project " + ent.project.name)).total).toBeGreaterThan(0);

  await issueService.archiveIssue(ent.actors.member, ent.org.id, i2.id);
  await emit("search.reindex_requested", { ...env, subjectKind: "issue", subjectId: i2.id });
  expect((await q(ent, "snake_case")).total).toBe(0);

  await commentService.updateComment(ent.actors.member, { orgId: ent.org.id, commentId: c.id, body: "edited wobble" });
  expect((await q(ent, "wobble", { projectId: ent.project.id })).total).toBe(1);
  const r = await runSearchReindexJob(ent.org.id);
  expect(r.failed).toBe(0);
  expect((await q(ent, "wobble", { projectId: ent.project.id })).total).toBe(1);
});
EOF
