  const c = await commentService.createComment(ent.actors.member, { orgId: ent.org.id, issueId: i1.id, body: "flaky deploy", parentId: null, mentionedUserIds: [] });
  expect((await q(ent, "100%")).items.map((h) => h.id)).toEqual([i2.id]);
  expect((await q(ent, "snake_case")).items.map((h) => h.id)).toEqual([i2.id]);
  expect((await q(ent, "SNAKE_CASE")).total).toBe(1);
  expect((await q(ent, "kind:comment flaky", { kinds: ["issue"] })).items.map((h) => h.id)).toEqual([c.id]);
  expect((await q(ent, "in:comments flaky", { kinds: ["issue"] })).total).toBe(1);
  expect((await q(ent, `project:${ent.project.id} deploy`)).total).toBe(2);
  expect((await q(ent, "project:nope deploy")).total).toBe(0);
  expect((await q(ent, "flaky", { projectId: ent.project.id })).total).toBe(1);

  await searchRepo.deleteSearchDocument(ent.org.id, "comment", c.id);
  await searchRepo.deleteSearchDocument(ent.org.id, "project", ent.project.id);
  const env = { orgId: ent.org.id, actorId: null, occurredAt: new Date().toISOString() as never };
  await emit("search.reindex_requested", { ...env, subjectKind: "comment", subjectId: c.id });
  await emit("search.reindex_requested", { ...env, subjectKind: "project", subjectId: ent.project.id });
  expect((await q(ent, "flaky", { projectId: ent.project.id })).total).toBe(1);
  expect((await q(ent, "kind:project " + ent.project.name)).total).toBeGreaterThan(0);

  await issueService.archiveIssue(ent.actors.member, ent.org.id, i2.id);
  await emit("search.reindex_requested", { ...env, subjectKind: "issue", subjectId: i2.id });
  expect((await q(ent, "snake_case")).total).toBe(0);

  await commentService.updateComment(ent.actors.member, { orgId: ent.org.id, commentId: c.id, body: "edited wobble" });
  expect((await q(ent, "wobble", { projectId: ent.project.id })).total).toBe(1);
  const r = await runSearchReindexJob(ent.org.id);
  expect(r.failed).toBe(0);
  expect((await q(ent, "wobble", { projectId: ent.project.id })).total).toBe(1);
});
